/* ============================================
   MILTHA — NT Master Loader
   Merges all NT parts into unified VERSES object
   Extends existing bible-data.js
   ============================================ */

// This file extends the VERSES object from bible-data.js
// Load after bible-data.js in HTML

(function() {
  // Merge all NT book data into the global VERSES object
  const NT_BOOKS = [
    NT_MATTHEW, NT_MARK, NT_LUKE,
    NT_ACTS, NT_ROMANS, NT_1CORINTHIANS,
    NT_GALATIANS, NT_EPHESIANS, NT_PHILIPPIANS, NT_COLOSSIANS,
    NT_1THESSALONIANS, NT_2TIMOTHY,
    NT_HEBREWS, NT_JAMES, NT_1PETER,
    NT_1JOHN, NT_JUDE, NT_REVELATION
  ];

  NT_BOOKS.forEach(book => {
    const id = book.meta.id;
    if (!window.VERSES) window.VERSES = {};
    if (!VERSES[id]) VERSES[id] = {};
    // Merge chapters
    Object.assign(VERSES[id], book.chapters);
    // Update book meta in BIBLE_BOOKS if present
    const bookEntry = window.BIBLE_BOOKS?.find(b => b.id === id);
    if (bookEntry) {
      bookEntry.loaded = true;
    }
  });

  console.log('MILTHA NT: All books loaded into VERSES');
})();
